-- Additive source-only private ledgers. No historical row is rebuilt or discarded.
CREATE TABLE sav_tracking(id TEXT PRIMARY KEY,command_key TEXT NOT NULL UNIQUE REFERENCES commands(key),case_id TEXT NOT NULL REFERENCES service_cases(id),status TEXT NOT NULL CHECK(status IN('IN_HOUSE','EXTERNAL','IN_REPAIR','READY','SENT_DISTRIBUTOR','RETURNED')),paid_repair_needed INTEGER NOT NULL CHECK(paid_repair_needed IN(0,1)),note TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES accounts(id),at INTEGER NOT NULL) STRICT;
CREATE TABLE sav_outcomes(case_id TEXT PRIMARY KEY REFERENCES service_cases(id),command_key TEXT NOT NULL UNIQUE REFERENCES commands(key),outcome TEXT NOT NULL CHECK(outcome IN('REPAIR_RETURN','REFUND','REFUSAL')),note TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES accounts(id),at INTEGER NOT NULL) STRICT;
CREATE TABLE sav_refunds(id TEXT PRIMARY KEY,command_key TEXT NOT NULL UNIQUE REFERENCES commands(key),case_id TEXT NOT NULL UNIQUE REFERENCES sav_outcomes(case_id),sale_id TEXT NOT NULL REFERENCES sales(id),amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 1 AND 99999999999999),method TEXT NOT NULL CHECK(method IN('Cash','Bank')),bank_method TEXT CHECK(bank_method IN('VIREMENT','CCP_BARIDIMOB')),shift_id TEXT REFERENCES shifts(id),actor_id TEXT NOT NULL REFERENCES accounts(id),at INTEGER NOT NULL,CHECK((method='Cash' AND shift_id IS NOT NULL AND bank_method IS NULL) OR (method='Bank' AND bank_method IS NOT NULL AND shift_id IS NULL))) STRICT;
CREATE TABLE sav_holding(phone_id TEXT PRIMARY KEY REFERENCES phones(id),case_id TEXT NOT NULL UNIQUE REFERENCES sav_outcomes(case_id)) STRICT;
CREATE TABLE sav_restocks(phone_id TEXT PRIMARY KEY REFERENCES sav_holding(phone_id),command_key TEXT NOT NULL UNIQUE REFERENCES commands(key),actor_id TEXT NOT NULL REFERENCES accounts(id),note TEXT NOT NULL,at INTEGER NOT NULL) STRICT;
-- Private: never select identity or amount in operational inventory/contracts/exports.
CREATE TABLE individual_purchases(phone_id TEXT PRIMARY KEY REFERENCES phones(id),command_key TEXT NOT NULL UNIQUE REFERENCES commands(key),store_id TEXT NOT NULL REFERENCES stores(id),surname TEXT NOT NULL,given_name TEXT NOT NULL,phone TEXT NOT NULL,photo_pending INTEGER NOT NULL CHECK(photo_pending=1),amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 1 AND 99999999999999),actor_id TEXT NOT NULL REFERENCES accounts(id),at INTEGER NOT NULL) STRICT;
CREATE TRIGGER sav_refund_cap BEFORE INSERT ON sav_refunds WHEN NEW.amount_minor + COALESCE((SELECT sum(amount_minor) FROM sav_refunds WHERE sale_id=NEW.sale_id),0) > COALESCE((SELECT cash_minor+bank_minor FROM sale_settlements WHERE sale_id=NEW.sale_id),(SELECT amount_minor FROM payments WHERE sale_id=NEW.sale_id)) + COALESCE((SELECT sum(r.amount_minor) FROM credit_repayments r WHERE r.sale_id=NEW.sale_id AND NOT EXISTS(SELECT 1 FROM credit_repayment_reversals x WHERE x.repayment_id=r.id)),0) OR EXISTS(SELECT 1 FROM sale_voids WHERE sale_id=NEW.sale_id) BEGIN SELECT RAISE(ABORT,'REJECTED'); END;
CREATE TRIGGER sav_refund_open BEFORE INSERT ON sav_refunds WHEN NEW.method='Cash' AND NOT EXISTS(SELECT 1 FROM shifts sh JOIN sales s ON s.store_id=sh.store_id WHERE sh.id=NEW.shift_id AND sh.state='OPEN' AND s.id=NEW.sale_id) BEGIN SELECT RAISE(ABORT,'SHIFT_CLOSED'); END;
CREATE TRIGGER immutable_sav_tracking_update BEFORE UPDATE ON sav_tracking BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_sav_tracking_delete BEFORE DELETE ON sav_tracking BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_sav_outcomes_update BEFORE UPDATE ON sav_outcomes BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_sav_outcomes_delete BEFORE DELETE ON sav_outcomes BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_sav_refunds_update BEFORE UPDATE ON sav_refunds BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_sav_refunds_delete BEFORE DELETE ON sav_refunds BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_sav_holding_update BEFORE UPDATE ON sav_holding BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_sav_holding_delete BEFORE DELETE ON sav_holding BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_sav_restocks_update BEFORE UPDATE ON sav_restocks BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_sav_restocks_delete BEFORE DELETE ON sav_restocks BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_individual_purchases_update BEFORE UPDATE ON individual_purchases BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_individual_purchases_delete BEFORE DELETE ON individual_purchases BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TABLE sav_exchanges(case_id TEXT PRIMARY KEY REFERENCES sav_outcomes(case_id),command_key TEXT NOT NULL UNIQUE REFERENCES commands(key),new_sale_key TEXT NOT NULL UNIQUE REFERENCES sales(command_key),at INTEGER NOT NULL) STRICT;
CREATE TRIGGER immutable_sav_exchanges_update BEFORE UPDATE ON sav_exchanges BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_sav_exchanges_delete BEFORE DELETE ON sav_exchanges BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
DROP TRIGGER active_serialized_sale;
CREATE TRIGGER active_serialized_sale BEFORE INSERT ON sale_lines WHEN NEW.kind='phone' AND EXISTS(SELECT 1 FROM sale_lines l WHERE l.item_id=NEW.item_id AND l.kind='phone' AND NOT EXISTS(SELECT 1 FROM sale_voids v WHERE v.sale_id=l.sale_id) AND NOT EXISTS(SELECT 1 FROM sav_holding h WHERE h.phone_id=l.item_id AND h.case_id IN(SELECT id FROM service_cases WHERE sale_id=l.sale_id))) BEGIN SELECT RAISE(ABORT,'PHONE_NOT_AVAILABLE'); END;
